def current_rows(events):
    best = {}
    for event in events:
        eid = event['id']
        key = (event['event_time'], event['seq'])
        if eid not in best or key > best[eid][0]:
            best[eid] = (key, event)
    result = []
    for eid, (_, event) in best.items():
        if event['op'] != 'D':
            result.append({'id': eid, 'value': event['value']})
    result.sort(key=lambda x: x['id'])
    return result
