import heapq

def stable_toposort(graph):
    # Map each node to its original insertion index
    indices = {node: i for i, node in enumerate(graph)}

    # Check for missing dependencies and compute in-degrees
    in_degree = {}
    dependents = {node: [] for node in graph}
    for node, deps in graph.items():
        in_degree[node] = len(deps)
        for dep in deps:
            if dep not in graph:
                raise ValueError(f"Missing dependency: {dep}")
            dependents[dep].append(node)

    # Min-heap of (index, node) for stable tie-breaking
    heap = []
    for node, deg in in_degree.items():
        if deg == 0:
            heapq.heappush(heap, (indices[node], node))

    result = []
    while heap:
        _, node = heapq.heappop(heap)
        result.append(node)
        for dependent in dependents[node]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, (indices[dependent], dependent))

    if len(result) != len(graph):
        raise ValueError("Cycle detected")

    return result
