def schema_drift(expected, actual):
    result = set()

    def add_leaf_paths(d, path):
        for k, v in d.items():
            if isinstance(v, dict):
                add_leaf_paths(v, path + [k])
            else:
                result.add(".".join(path + [k]))

    def compare(e, a, path):
        # missing keys in expected
        for k in e:
            if k not in a:
                if isinstance(e[k], dict):
                    add_leaf_paths(e[k], path + [k])
                else:
                    result.add(".".join(path + [k]))
        # extra keys in actual
        for k in a:
            if k not in e:
                if isinstance(a[k], dict):
                    add_leaf_paths(a[k], path + [k])
                else:
                    result.add(".".join(path + [k]))
        # common keys
        for k in e:
            if k in a:
                ev = e[k]
                av = a[k]
                if isinstance(ev, dict) and isinstance(av, dict):
                    compare(ev, av, path + [k])
                elif isinstance(ev, dict) or isinstance(av, dict):
                    # one is dict, the other is not -> type mismatch
                    result.add(".".join(path + [k]))
                else:
                    # both leaves (strings)
                    if ev != av:
                        result.add(".".join(path + [k]))

    compare(expected, actual, [])
    return sorted(result)
